        const cost = dp[j][t - 1] + maxVal;
        if (cost < dp[i][t]) {
          dp[i][t] = cost;
          split[i][t] = j;
        }
      }
    }
  }

  const blocks = [];
  let i = n, t = k;
  while (t > 0) {
    const j = split[i][t];
    blocks.unshift({ start: j + 1, end: i });
    i = j;
    t--;
  }

  return { minSum: dp[n][k], blocks };
}
